use App\Http\Controllers\Controller;use App\Models\Staff;use App\Services\Hr\Meals\MealProgrammeService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class MealVarianceController extends Controller{
 public function store(Request$r,string$orderId):JsonResponse{$this->enabled();$d=$r->validate(['reason_code'=>['required','string','max:60'],'reason'=>['required','string','max:3000'],'lines'=>['required','array','min:1'],'lines.*.vendor_order_line_id'=>['nullable','uuid'],'lines.*.employee_order_id'=>['nullable','uuid'],'lines.*.replacement_menu_item_id'=>['nullable','uuid'],'lines.*.adjustment_type'=>['required',Rule::in(['supplier_credit','substitution','employee_refund','employer_absorption','wastage','quantity_correction'])],'lines.*.quantity_delta'=>['required','integer'],'lines.*.supplier_amount_delta'=>['required','numeric'],'lines.*.employer_amount_delta'=>['required','numeric'],'lines.*.employee_amount_delta'=>['required','numeric'],'lines.*.resolution_snapshot'=>['required','array'],'lines.*.reason'=>['required','string','max:2000']]);$order=DB::table('hr_meal_vendor_orders')->where('id',$orderId)->first();abort_unless($order,404);$this->company($r,$order->company_id);abort_unless($order->status==='delivered',409,'Only a delivered vendor order may receive a variance case.');return DB::transaction(function()use($r,$d,$order){$id=(string)Str::uuid();DB::table('hr_meal_variance_cases')->insert(['id'=>$id,'vendor_order_id'=>$order->id,'reason_code'=>$d['reason_code'],'reason'=>$d['reason'],'status'=>'pending_approval','prepared_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);foreach($d['lines']as$line){if(isset($line['vendor_order_line_id']))abort_unless(DB::table('hr_meal_vendor_order_lines')->where('id',$line['vendor_order_line_id'])->where('vendor_order_id',$order->id)->exists(),422);if(isset($line['employee_order_id']))abort_unless(DB::table('hr_meal_employee_orders')->where('id',$line['employee_order_id'])->where('program_version_id',$order->program_version_id)->whereDate('service_date',$order->service_date)->exists(),422);abort_unless(round((float)$line['supplier_amount_delta'],4)===round((float)$line['employer_amount_delta']+(float)$line['employee_amount_delta'],4),422,'Each variance line must preserve supplier equals employer plus employee allocation.');$line['id']=(string)Str::uuid();$line['variance_case_id']=$id;$line['resolution_snapshot']=json_encode($line['resolution_snapshot'],JSON_THROW_ON_ERROR);$line['created_at']=$line['updated_at']=now();DB::table('hr_meal_variance_lines')->insert($line);}return response()->json(['status'=>'success','data'=>DB::table('hr_meal_variance_cases')->find($id)],201);});}
 public function decide(Request$r,string$id):JsonResponse{$this->enabled();$d=$r->validate(['decision'=>['required',Rule::in(['approved','rejected'])],'reason'=>['required','string','max:2000']]);return DB::transaction(function()use($r,$id,$d){$case=DB::table('hr_meal_variance_cases as c')->join('hr_meal_vendor_orders as o','o.id','=','c.vendor_order_id')->where('c.id',$id)->select('c.*','o.company_id','o.total_amount','o.employer_amount','o.employee_amount')->lockForUpdate()->first();abort_unless($case,404);$this->company($r,$case->company_id);abort_unless($case->status==='pending_approval',409);abort_if($case->prepared_by===$r->user()->id,409,'Variance preparer cannot approve the same case.');if($d['decision']==='approved'){$totals=DB::table('hr_meal_variance_lines')->where('variance_case_id',$id)->selectRaw('coalesce(sum(supplier_amount_delta),0) supplier_delta, coalesce(sum(employer_amount_delta),0) employer_delta, coalesce(sum(employee_amount_delta),0) employee_delta')->first();abort_if((float)$case->total_amount+(float)$totals->supplier_delta<0||(float)$case->employer_amount+(float)$totals->employer_delta<0||(float)$case->employee_amount+(float)$totals->employee_delta<0,422,'Approved variance totals cannot create negative balances.');foreach(DB::table('hr_meal_variance_lines')->where('variance_case_id',$id)->whereNotNull('employee_order_id')->get()as$line){$employee=DB::table('hr_meal_employee_orders')->find($line->employee_order_id);abort_if((float)$employee->employee_share_amount+(float)$line->employee_amount_delta<0||(float)$employee->employer_subsidy_amount+(float)$line->employer_amount_delta<0,422,'Variance would create a negative employee allocation.');}}DB::table('hr_meal_variance_cases')->where('id',$id)->update(['status'=>$d['decision'],'approved_by'=>$r->user()->id,'approved_at'=>now(),'decision_reason'=>$d['reason'],'updated_at'=>now()]);return response()->json(['status'=>'success','data'=>DB::table('hr_meal_variance_cases')->find($id)]);});}
 public function reconcile(Request$r,string$id,MealProgrammeService$s):JsonResponse{$this->enabled();return DB::transaction(function()use($r,$id,$s){$o=DB::table('hr_meal_vendor_orders')->where('id',$id)->lockForUpdate()->first();abort_unless($o,404);$this->company($r,$o->company_id);abort_unless($o->status==='delivered',409);$deliveryLines=DB::table('hr_meal_vendor_order_lines')->where('vendor_order_id',$id)->get();$hasVariance=$deliveryLines->contains(fn($line)=>$line->delivered_quantity===null||(int)$line->accepted_quantity!==(int)$line->ordered_quantity||((int)$line->consumed_quantity+(int)$line->wasted_quantity)!==(int)$line->accepted_quantity);$case=DB::table('hr_meal_variance_cases')->where('vendor_order_id',$id)->first();if($hasVariance)abort_unless($case&&$case->status==='approved',409,'An approved variance case is required before reconciliation.');if($case&&$case->status!=='approved')abort(409,'The variance case is not approved.');$variance=$case?DB::table('hr_meal_variance_lines')->where('variance_case_id',$case->id)->get():collect();$supplierDelta=(float)$variance->sum('supplier_amount_delta');$employerDelta=(float)$variance->sum('employer_amount_delta');$employeeDelta=(float)$variance->sum('employee_amount_delta');$program=DB::table('hr_meal_program_versions')->find($o->program_version_id);$vendor=DB::table('hr_meal_vendors')->find($o->vendor_id);$employeeOrders=DB::table('hr_meal_employee_orders')->where('program_version_id',$o->program_version_id)->whereDate('service_date',$o->service_date)->get();$allocations=$employeeOrders->map(function($x)use($variance){$adjustments=$variance->where('employee_order_id',$x->id);return['employee_order_id'=>$x->id,'staff_id'=>$x->staff_id,'base_employee_share'=>$x->employee_share_amount,'employee_adjustment'=>(float)$adjustments->sum('employee_amount_delta'),'final_employee_share'=>(float)$x->employee_share_amount+(float)$adjustments->sum('employee_amount_delta')];})->values()->all();$base=['vendor_order_id'=>$id,'supplier_reference'=>$vendor->canonical_supplier_reference,'vendor_id'=>$vendor->id,'service_date'=>$o->service_date,'currency'=>$o->currency,'order_checksum'=>$o->order_checksum,'variance_case_id'=>$case?->id,'variance_checksum'=>hash('sha256',json_encode($variance,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR))];$accounting=$base+['supplier_payable_amount'=>(float)$o->total_amount+$supplierDelta,'employer_expense_amount'=>(float)$o->employer_amount+$employerDelta,'employee_receivable_amount'=>(float)$o->employee_amount+$employeeDelta];$recovery=$base+['employee_recovery_amount'=>(float)$o->employee_amount+$employeeDelta,'employee_recovery_mode'=>$program->employee_recovery_mode,'employee_allocations'=>$allocations,'direct_and_payroll_mutually_exclusive'=>true];$this->outbox($o,'meal_vendor_order_accounting_ready','accounting',$accounting);$this->outbox($o,'meal_employee_recovery_ready',$program->employee_recovery_mode==='payroll'?'payroll':'accounting_direct',$recovery);DB::table('hr_meal_vendor_orders')->where('id',$id)->update(['status'=>'reconciled','updated_at'=>now()]);DB::table('hr_meal_employee_orders')->whereIn('id',$employeeOrders->pluck('id'))->update(['status'=>'reconciled','updated_at'=>now()]);$s->event('vendor_order',$id,'reconciled','delivered','reconciled',['accounting_event'=>'meal_vendor_order_accounting_ready','recovery_event'=>'meal_employee_recovery_ready','variance_case_id'=>$case?->id],$r->user()->id);return response()->json(['status'=>'success','data'=>DB::table('hr_meal_vendor_orders')->find($id)]);});}
 private function outbox(object$o,string$event,string$target,array$payload):void{DB::table('hr_accounting_outbox')->insert(['id'=>(string)Str::uuid(),'company_id'=>$o->company_id,'event_type'=>$event,'aggregate_type'=>'meal_vendor_order','aggregate_id'=>$o->id,'target_system'=>$target,'payload'=>json_encode($payload,JSON_THROW_ON_ERROR),'payload_checksum'=>hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)),'status'=>'pending','available_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}private function actor(Request$r):Staff{return Staff::query()->where('user_id',$r->user()->id)->firstOrFail();}private function company(Request$r,string$id):void{abort_unless($this->actor($r)->company_id===$id,403,'Meal variance data is outside your legal entity.');}private function enabled():void{abort_unless(config('hr.features.meals',false),409,'The optional meal programme is not enabled for this deployment.');}
